,"hash":"84ada0ea1872d764ebbb40f57526b3f4","source_hash":"4a11e8f30cbc227a55df4b621b777120","phase":"core"},{"schema":"public","proname":"math_learning","args":"p_request jsonb","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"hash":"09c463d28cd9645a7918fc6b11e48cea","source_hash":"55e47f50d47f26e6516ccefc0d37d43b","phase":"core"},{"schema":"public","proname":"math_reveal_hint","args":"uuid, uuid","owner":"math_executor","acl":"{math_executor=X/math_executor,authenticated=X/math_executor,postgres=X/math_executor}","config":["search_path=\"\""],"hash":"b03a65f6f8f9ca6fb590ecc119e4e109","source_hash":"686442c943ae1b7f7730ec0958215abd","phase":"core"},{"schema":"public","proname":"math_session_read","args":"p_run uuid","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"hash":"6a12564da469a5e6c6d1a8dea2ca487a","source_hash":"259c23f3ea6b195cb8507abdedfba482","phase":"core"},{"schema":"public","proname":"math_session_submit","args":"p_exam uuid, p_key uuid, p_attempts uuid[], p_parent uuid","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"hash":"b4b592e12240af3d87efda7b8e03aa71","source_hash":"d2863f2d70053b939132f6dad087c638","phase":"core"},{"nspname":"math_private","proname":"evaluation_admission","args":"","owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=\"\""],"hash":"99e6437c3e6cca4c08f0d06f78896b80","schema":"math_private","config":["search_path=\"\""],"phase":"scope"},{"nspname":"public","proname":"math_catalog","args":"p_limit integer","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres}","proconfig":["search_path=\"\""],"hash":"6727dac14c4ed845a6564787405bfbcd","schema":"public","config":["search_path=\"\""],"phase":"scope"},{"nspname":"public","proname":"essay_material_runtime_package","args":"p_exam uuid, p_digest text","owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres,essay_worker=X/postgres}","proconfig":["search_path=\"\""],"hash":"ccf30a6441346d6d203f35b7052e0433","schema":"public","config":["search_path=\"\""],"phase":"scope"},{"schema":"essay_beta_private","name":"eligible","args":"p_grant uuid, p_exam uuid","owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=\"\""],"hash":"5cc8547ed15874d932d84e6d74009552","proname":"eligible","config":["search_path=\"\""],"phase":"beta"},{"schema":"essay_beta_private","name":"credit_source","args":"p_account uuid, p_exam uuid","owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=\"\""],"hash":"09fc9d66ee9286fac0f6bfed03046d3b","proname":"credit_source","config":["search_path=\"\""],"phase":"beta"},{"schema":"public","args":"p_exam uuid, p_key uuid, p_attempts uuid[], p_parent uuid","owner":"postgres","acl":"{postgres=X/postgres,authenticated=X/postgres}","hash":"03456f71b861151cfe523c06a075d8ca","name":"math_session_submit","proconfig":["search_path=\"\""],"proname":"math_session_submit","config":["search_path=\"\""],"phase":"beta"}]'::jsonb)),
function_checks as(
select e->>'phase' phase,e->>'schema' schema,e->>'proname' name,e->>'args' args,
p.oid is not null present,
md5(pg_get_functiondef(p.oid)) definition_md5,pg_get_userbyid(p.proowner) owner,p.proacl::text acl,p.proconfig config,
md5(pg_get_functiondef(p.oid))=e->>'hash' and pg_get_userbyid(p.proowner)=e->>'owner' and p.proacl::text=e->>'acl' and to_jsonb(p.proconfig)=e->'config' as matches
from expected left join pg_namespace n on n.nspname=e->>'schema' left join pg_proc p on p.pronamespace=n.oid and p.proname=e->>'proname' and pg_get_function_identity_arguments(p.oid)=e->>'args'
)
select jsonb_build_object(
'function_checks',(select jsonb_agg(to_jsonb(f) order by phase,schema,name) from function_checks f),
'memberships',(select jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'grantor',pg_get_userbyid(grantor),'admin',admin_option,'inherit',inherit_option,'set',set_option)) from pg_auth_members where member='postgres'::regrole and roleid in('math_executor'::regrole,'essay_executor'::regrole)),
'temporary_privileges',jsonb_build_object('math_public_create',has_schema_privilege('math_executor','public','CREATE'),'math_private_create',has_schema_privilege('math_executor','math_private','CREATE'),'essay_math_create',has_schema_privilege('essay_executor','math_private','CREATE'),'math_evaluation_references',has_table_privilege('math_executor','public.math_evaluations','REFERENCES')),
'new_objects',(select jsonb_agg(jsonb_build_object('name',x,'present',to_regprocedure(x) is not null)) from unnest(array['public.math_coaching(jsonb)','public.essay_math_coaching(jsonb)','public.math_session_quote(uuid)','public.math_session_continue(uuid,uuid,uuid[],uuid,integer)','public.math_session_quote_source(uuid,uuid)','public.math_session_continue_source(uuid,uuid,uuid[],uuid,integer,uuid)'])x),
'runtime_control',(select to_jsonb(c) from math_private.runtime_control c),
'beta_campaigns',(select jsonb_agg(jsonb_build_object('id',id,'starts_on',starts_on,'ends_on',ends_on,'enabled',enabled,'daily_limit',daily_limit,'policy_version',policy_version)) from essay_beta_private.campaigns),
'beta_scope_counts',(select jsonb_build_object('total',count(*),'has_math',count(*) filter(where has_math)) from essay_beta_private.exam_scope),
'counts',jsonb_build_object('credit_accounts',(select count(*) from public.credit_accounts),'credit_grants',(select count(*) from public.credit_grants),'credit_transactions',(select count(*) from public.credit_transactions),'essay_billing_decisions',(select count(*) from public.essay_billing_decisions),'math_session_runs',(select count(*) from math_private.session_runs),'essay_exam_runs',(select count(*) from essay_exam_private.runs)),
'storage',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) from storage.buckets where id like '%math%' or id like '%essay%'),
'migrations',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'version',version)),'[]') from supabase_migrations.schema_migrations where name like '%math_commerce%' or name like '%task16%')
) audit;